                <Progress.Section
                    value={(100.0 * player.gamesDrawn) / gamesPlayed}
                    color="yellow"
                />
                <Progress.Section
                    value={(100.0 * player.gamesLost) / gamesPlayed}
                    color="red"
                />
            </Progress.Root>
        </Tooltip>
    );
};

